exercises.solution:
import UIKit
@MainActor
func reveal(_ banner: UIView) {
    banner.isHidden = false
    let finish = {
        banner.alpha = 1
        banner.transform = .identity
    }

    if UIAccessibility.isReduceMotionEnabled {
        finish()
    } else {
        banner.alpha = 0
        banner.transform = CGAffineTransform(
            translationX: 0, y: -12
        )
        UIView.animate(withDuration: 0.2, animations: finish)
    }
}

